// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 t) internal {
        vm.assume(t >= block.timestamp);
        assertTrue(c.pastBlockTime() <= t);
    }

    function testFuzz_run(uint256 t) public {
        _run(t);
    }

    receive() external payable {}
}
